import sys

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    if m == n - 1:
        return ""

    edges = []
    for i in range(m):
        a, b, e = map(int, lines[1 + i].split())
        edges.append((a, b, e))

    # Kruskal's algorithm to find MST
    parent = list(range(n + 1))
    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[px] = py
            return True
