import sys
from functools import lru_cache

# Increase recursion depth for deep recursion if needed
sys.setrecursionlimit(2000)

def parse_input(s):
    """Parse the input string into integers"""
    lines = s.strip().split('\n')
    first_line = lines[0].split()
    n, m, k = int(first_line[0]), int(first_line[1]), int(first_line[2])

    transformers = []
    for i in range(1, k + 1):
        parts = lines[i].split()
        if i < len(lines):
            x, y, d, t, e = map(int, parts)
            transformers.append({'x': x, 'y': y, 'd': d, 't': t, 'e': e})

    return n, m, k, transformers

def get_transformer_positions(transformer, step):
    """
    Get transformer's position at step (time from start at t=0)
    step corresponds to time = t + step since transformer starts at time t
    """
    x = transformer['x']
    y = transformer['y']
    d = transformer['d']
    t = transformer['t']

    if step < t:
        return None

    time_since_start = step - t
    k = time_since_start % 4

    # Based on the pattern: {(x,y),(x+d,y-d),(x+d,y),(x,y+d)}
    # At k=0: (x, y)
    # At k=1: (x+d, y-d)
    # At k=2: (x+d, y)
    # At k=3: (x, y+d)

    if k == 0:
        return (x, y, d)
    elif k == 1:
        return (x + d, y - d, d)
    elif k == 2:
        return (x + d, y, d)
    else:  # k == 3
        return (x, y + d, d)

def compute_energy_costs(n, m, transformers):
    """
    Compute the total energy cost at each position (i, j) for each possible step count
    step_count = i + j (time elapsed from start at (0,0))
    """
    # dp[step_count] = dictionary mapping (i, j) to list of (transformer_idx, cost)
    max_step = n + m - 2  # Maximum steps to reach (n-1, m-1)

    # MeetingTable[step][(i, j)] = total energy at step (i, j) in exactly step steps from start
    meeting_costs = {}

    for transformer in transformers:
        for step in range(max_step + 1):
            pos = get_transformer_positions(transformer, step)
            if pos is None:
                continue

            ix, iy, d = pos
            if 0 <= ix < n and 0 <= iy < m:
                meeting_costs.setdefault(step, {}).setdefault((ix, iy), []).append(transformer['e'])

    # Aggregate costs by position and step
    aggregated = {}
    for step, pos_map in meeting_costs.items():
        for pos, costs in pos_map.items():
            key = (step, pos[0], pos[1])
            aggregated[key] = sum(costs)  # Plus it's in a meeting

    return aggregated

def solve_dp(n, m, meeting_costs):
    """
    Solve using DP: dp[i][j] = minimum energy to reach cell (i,j)
    """
    # Initialize dp table
    # dp[i][j] = minimum energy to reach (i,j)
    INF = float('inf')
    dp = [[INF] * m for _ in range(n)]
    dp[0][0] = 0

    # Precompute meeting costs by cell
    meeting_by_cell = {}
    for (step, i, j), cost in meeting_costs.items():
        meeting_by_cell[(i, j)] = meeting_by_cell.get((i, j), 0) + cost

    max_step = n + m - 2

    for s in range(1, max_step + 1):
        for i in range(min(s, n - 1)):
            j = s - i
            if 0 <= j < m:
                dp[i][j] = min(
                    dp[i][j],
                    dp[i][j - 1] + meeting_by_cell.get((i, j), 0)
                )

        for j in range(min(s, m - 1)):
            i = s - j
            if 0 <= i < n:
                dp[i][j] = min(
                    dp[i][j],
                    dp[i - 1][j] + meeting_by_cell.get((i, j), 0)
                )

    return dp[n - 1][m - 1]

def solution(s):
    n, m, k, transformers = parse_input(s)

    # Compute energy costs at each (step, i, j)
    meeting_costs = compute_energy_costs(n, m, transformers)

    # Solve with DP
    result = solve_dp(n, m, meeting_costs)

    # Return result
    return str(result)

if __name__ == "__main__":
    # Test
    test1 = "3 3 5\n0 1 1 0 7\n1 1 1 0 10\n1 1 1 1 2\n1 1 1 2 2\n0 1 1 2 3\n"
    print(solution(test1))
