def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    # Parse diagonals
    diagonals = []
    for i in range(1, m + 1):
        a, b = map(int, lines[i].split())
        diagonals.append((min(a, b), max(a, b)))

    # Build the graph structure
    # Regions are formed by the polygon edges and diagonals
    # We'll use BFS to find regions starting from each vertex

    # Adjacency list for polygon vertices
    adj = {i: [] for i in range(1, n + 1)}
    for i in range(1, n):
        adj[i].append(i + 1)
    if n > 1:
        adj[n].append(1)

    for a, b in diagonals:
        adj[a].append(b)
        adj[b].append(a)

    # Find all regions using planar graph approach
    # A region is bounded by a cycle of adjacent vertices
    regions = []
    used_edges = set()

    def get_region_boundaries(start, edges_seen):
        """Trace a region boundary starting from vertex"""
        bound = [start]
        curr = start
        next_vertex = 0

        while True:
            neighbors = adj[curr]
            found = False
            for nxt in neighbors:
                if (curr, nxt) in used_edges or (nxt, curr) in edges_seen:
                    found = True
                    if (nxt, curr) not in edges_seen:
                        used_edges.add((curr, nxt))
                    break
            if not found:
                break
            bound.append(nxt)
            edges_seen.add((curr, nxt))
            curr = nxt
            if curr == start or len(bound) > n:
                break

        return bound

    # Find regions by looking at each edge
    all_edges = set()
    for i in range(1, n + 1):
        for neighbor in adj[i]:
            edge = tuple(sorted([i, neighbor]))
            if edge not in all_edges:
                all_edges.add(edge)

    # For small graphs, use a different approach - find all simple cycles
    # Build graph with just polygon edges and diagonals
    graph_adj = {i: [] for i in range(1, n + 1)}
    graph_edges = set()

    for i in range(1, n):
        u, v = i, i + 1
        graph_adj[u].append(v)
        graph_adj[v].append(u)
        graph_edges.add((min(u, v), max(u, v)))
    if n > 1:
        u, v = n, 1
        graph_adj[u].append(v)
        graph_adj[v].append(u)
        graph_edges.add((min(u, v), max(u, v)))

    for a, b in diagonals:
        graph_adj[a].append(b)
        graph_adj[b].append(a)
        graph_edges.add((min(a, b), max(a, b)))

    # Find regions using DFS approach
    # Each region is a face in the planar graph
    def dfs_visit(u, v, path, face):
        if v not in graph_adj[u]:
            return []

        path.append(v)

        if len(path) > n:
            path.pop()
            return []

        face_vertices = path[:-1]

        neighbors = graph_adj[v]
        found_edge = False
        for next_v in neighbors:
            if next_v not in path:
                continue

            edge = tuple(sorted([v, next_v]))
            if edge in graph_edges:
                face_vertices.append(next_v)
                path.append(next_v)
                result = dfs_visit(v, next_v, path, face_vertices)
                path.pop()

                if result:
                    return result
                else:
                    face_vertices = path[:]
                return path[:]

