    def can_see(x, y, dx, dy):
        cx, cy = x + dx, y + dy
        while 1 <= cx <= n and 1 <= cy <= n:
            if lights[cx - 1][cy - 1] == 1:
                return True
            cx += dx
            cy += dy
        return False

    # DFS with backtracking
    def dfs(x, y):
        # Goal: all lights off and we're at start
        if all_off() and x == 1 and y == 1:
            return True

        # Turn off light at current position
        if lights[x - 1][y - 1] == 1:
            result.append('2')
            lights[x - 1][y - 1] = 0

        # Explore directions
        directions = [(0, -1, 'L'), (0, 1, 'R'), (-1, 0, 'U'), (1, 0, 'D')]

        for dx, dy, d in directions:
            nx, ny = x + dx, y + dy

            if 1 <= nx <= n and 1 <= ny <= n:
                # Can see light in this direction?
                if can_see(x, y, dx, dy):
                    result.append(d)
                    if dfs(nx, ny):
