                    elif color[v] == color[u]:
                        is_bipartite = False
                        break

    if is_bipartite:
        n0_12 = n1  # 2^num_components
    else:
        n0_12 = 0

    # Apply inclusion-exclusion
    # Answer = total - 2*|N0| - |N1| + |N0∩N1| + |N0∩N2| + |N1∩N2| - |N0∩N1∩N2|
    # |N0∩N1| = 1 (all 1s), |N1∩N2| = 1 (all 0s), |N0∩N1∩N2| = 0
    # For m > 0: Answer = 2^n - 2*n0 - n1 + 1 + n0_12 + 1 - 0
    #                 = 2^n - 2*n0 - n1 + n0_12 + 2

    ans = total - 2 * n0 - n1 + n0_12 + 2

    return f"{ans}\n"
