    if n == 1:
        # We need b > 1 and b < x
        if x <= 2:
            return "-1\n"
        # Valid bases are from 2 to x-1, largest is x-1
        return f"{x-1}\n"

    # For n > 1 and x <= 2, no valid base exists since b > 1 required
    if x <= 2:
        return "-1\n"

    result = -1

    # Factorize n for order checking
    n_factors = get_prime_factors(n)

    # Iterate m to find primes p = m*n + 1 where p < x is possible
    max_m = x // n + 1

    for m in range(1, max_m + 2):
