            pass

        # Check primality
        if not is_prime(p):
            continue

        # Check if there exists valid b < x with ord_p(b) = n
        # This means: b^n ≡ 1 (mod p) AND for all proper divisors d of n, b^(n/d) ≢ 1 (mod p)
        # We search for the largest such b

        # For safety and performance, limit how far we search downwards
        max_iterations = 20000
        iteration_count = 0
        best_for_p = -1

        # Search from x-1 downward
        for b in range(x - 1, 2, -1):
            iteration_count += 1
            if iteration_count > max_iterations:
                break

            # Check order condition
            if pow(b, n, p) != 1:
                continue

            valid_order = True
            for d in n_factors:
                if pow(b, n // d, p) == 1:
                    valid_order = False
                    break

            if valid_order:
                best_for_p = b
                break  # Found largest for this p

        if best_for_p > result:
            result = best_for_p

        # Optimization: if we found x-1, we can't do better
        if result == x - 1:
            break

    if result == -1:
        return "-1\n"
    return f"{result}\n"
